const $=s=>document.querySelector(s);const main=$('#main');
const categories=[['Paper & printing','A4 paper, photocopy paper and everyday print essentials.','paper'],['Writing essentials','Pens, pencils, highlighters and markers.','pens'],['Files & office supplies','Files, folders and supplies for an organised office.','files'],['Books & notebooks','Exercise books and notebooks for learning and work.','books'],['School stationery packs','Prepare a list by grade, class or learning programme.','pack'],['Art & craft','Creative essentials for classrooms and projects.','art'],['Rulers & geometry','Rulers, geometry sets and measuring essentials.','ruler'],['Calculators','Share the model and functions your learners or team need.','calc']];
function icon(kind){const a={paper:'<path d="M28 15h58l17 17v53H28z" fill="#fff" stroke="#a5b2bc"/><path d="M86 15v19h17" fill="#dfb454"/><path d="M17 27v68h66" fill="none" stroke="#06264d" stroke-width="8"/><path d="M40 49h47M40 60h47M40 71h31" stroke="#b7c3cc" stroke-width="3"/>',pens:'<g transform="rotate(20 60 50)"><path d="M32 15h12v58l-6 13-6-13z" fill="#dfb454"/><path d="M56 10h13v65l-7 13-6-13z" fill="#06264d"/><path d="M82 22h10v52l-5 12-5-12z" fill="#819a9c"/><path d="M32 25h12M56 23h13M82 33h10" stroke="white" stroke-width="3"/></g>',files:'<rect x="17" y="24" width="27" height="63" rx="2" fill="#06264d"/><rect x="47" y="16" width="27" height="71" rx="2" fill="#dfb454"/><rect x="77" y="28" width="27" height="59" rx="2" fill="#7e999d"/><path d="M25 36h11M55 29h11M85 40h11" stroke="white" stroke-width="4"/><circle cx="30" cy="73" r="4" fill="white"/><circle cx="60" cy="73" r="4" fill="white"/><circle cx="90" cy="73" r="4" fill="white"/>',books:'<path d="M17 62h84v19H17z" fill="#06264d"/><path d="M22 44h78v18H22z" fill="#dfb454"/><path d="M30 25h66v19H30z" fill="#829b9e"/><path d="M27 70h65M31 52h59M39 33h47" stroke="#fff" stroke-width="4"/>',pack:'<path d="M27 38q0-17 17-17h35q17 0 17 17v48H27z" fill="#06264d"/><path d="M48 21v-6h26v6" fill="none" stroke="#b98e37" stroke-width="5"/><rect x="38" y="55" width="48" height="24" rx="5" fill="#dfb454"/><path d="M40 45h42M49 65h25" stroke="white" stroke-width="3"/>',art:'<path d="M29 48h62l-7 39H36z" fill="#dfb454"/><path d="M43 15l5 36M66 12v38M88 20L76 51" stroke="#06264d" stroke-width="7"/><path d="M39 6l3 12M66 3v12M92 10l-5 14" stroke="#819a9c" stroke-width="10"/>',ruler:'<path d="M21 83L100 9v74z" fill="#dfb454"/><path d="M49 71l38-35v35z" fill="#efeee8"/><path d="M36 73l-5-5M47 63l-5-5M58 53l-5-5M69 43l-5-5M80 33l-5-5" stroke="#06264d" stroke-width="2"/>',calc:'<rect x="31" y="9" width="62" height="80" rx="6" fill="#06264d"/><rect x="41" y="19" width="42" height="20" rx="2" fill="#d4dfd0"/><path d="M42 51h8m8 0h8m8 0h8M42 64h8m8 0h8m8 0h8M42 77h8m8 0h8" stroke="white" stroke-width="5"/><path d="M75 70h8v13h-8z" fill="#dfb454"/>'};return `<svg viewBox="0 0 120 100" aria-hidden="true">${a[kind]}</svg>`}
let items=restoreBasket();let formData={};let step=0;let selectedFiles=[];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
function updateCount(){saveShoppingCart();saveBasket();document.querySelectorAll('.basket-count').forEach(e=>e.textContent=items.length?`(${items.length})`:'')}
const buyingDetails={
 paper:['Size, paper weight, colour and sheets per ream. Specify reams or boxes.','A4 · 80 gsm · white · 500 sheets per ream'],
 pens:['Ink colour, tip size and pen type. State individual pens or packs and the pack count.','Blue ballpoint · medium tip · pack of 10'],
 files:['File type, size, spine width and colour. Specify individual files or a box quantity.','A4 lever arch · 70 mm spine · each'],
 books:['Book size, page count, ruling and binding. State books per learner or total books.','A4 exercise book · 72 pages · feint and margin · each'],
 pack:['Contents per pack, number of packs, grade and any labelling instructions.','30 learner packs · item quantities per pack on attached list'],
 art:['Material, colour, size or volume. Include age or safety requirements where relevant.','Coloured pencils · 12 colours · one set per learner'],
 ruler:['Length, material and components required in each set.','30 cm ruler · clear plastic · each'],
 calc:['Exact model or required functions. State whether alternatives are acceptable.','Scientific calculator · exact model to be specified · each']
};
const exampleItems=[{description:'A4 photocopy paper, 80 gsm, white',quantity:10,unit:'Ream of 500 sheets'},{description:'Blue ballpoint pens, medium tip',quantity:5,unit:'Pack of 10 pens'},{description:'A4 exercise book, 72 pages, feint and margin',quantity:60,unit:'Each'}];
function cards(filter=''){return categories.filter(c=>(c[0]+' '+c[1]+' '+buyingDetails[c[2]].join(' ')).toLowerCase().includes(filter.toLowerCase())).map(c=>`<article class="supply-row"><div class="supply-icon">${icon(c[2])}</div><div><h3>${c[0]}</h3><p>${c[1]}</p></div><div class="spec-guide"><span class="row-label">What to specify</span><p>${buyingDetails[c[2]][0]}</p><small>Example: ${buyingDetails[c[2]][1]}</small></div><button class="btn outline" data-add="${c[2]}">Add category</button></article>`).join('')}
function cta(){return `<section class="cta"><div class="wrap"><div><h2>Prepare your stationery request</h2><p>Include quantities, pack sizes, your delivery town and required date.</p></div><a class="btn dark" href="#quote">Start a quote request</a></div></section>`}
function examples(){return `<div class="table-scroll"><table class="buying-table"><caption>Example requirements — edit these to match your list. Availability and prices require confirmation.</caption><thead><tr><th scope="col">Item specification</th><th scope="col">Order quantity</th><th scope="col">Equivalent total</th><th scope="col"><span class="sr-only">Action</span></th></tr></thead><tbody>${exampleItems.map((x,i)=>`<tr><th scope="row">${x.description}<small>${x.unit}</small></th><td>${x.quantity} ${i===0?'reams':i===1?'packs':'books'}</td><td>${['5,000 sheets','50 pens','60 books'][i]}</td><td><button type="button" data-example="${i}">Use this example</button></td></tr>`).join('')}</tbody></table></div>`}
function home(){return `<section class="shop-hero"><div class="wrap shop-hero-inner"><div><span class="eyebrow">Lepetse stationery supply</span><h1>Office and school stationery,<br>supplied to your requirements.</h1><p>Prepare a quotation request for everyday office supplies, school packs or a formal procurement list.</p><div class="actions"><a class="btn dark" href="#stationery">Browse products</a></div><small>Once-off orders · Office replenishment · School packs</small></div><div class="hero-products" aria-label="Representative stationery illustrations">${['paper-a4','file-lever','pens-blue'].map(id=>{const p=products.find(p=>p.id===id);return `<a href="#product-${p.id}" class="hero-product">${productArt(p)}<span>${p.name}</span></a>`}).join('')}<p>Generated product images · final range to be confirmed</p></div></div></section><div class="shop-category-bar wrap">${categories.map(c=>`<a href="#stationery?category=${c[2]}">${c[0]}</a>`).join('')}</div><section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Browse the range</span><h2>Office and classroom essentials</h2></div><a class="text-link" href="#stationery">View all products</a></div><p class="sample-note">Sample catalogue with AI-generated images. Final brands, availability and prices will be confirmed before launch.</p><div class="product-grid featured-grid">${products.filter(p=>['paper-a4','pens-blue','file-lever','exercise-72'].includes(p.id)).map(productCard).join('')}</div></div></section><section class="procurement-strip"><div class="wrap"><div><span class="eyebrow">Bulk orders and formal RFQs</span><h2>Already have a stationery list?</h2><p>Attach your spreadsheet, school list or RFQ document. You can prepare an enquiry without selecting every product again.</p><a class="btn" href="#upload">Upload your list</a></div><ul><li>Include quantities and pack sizes.</li><li>Add your delivery location and required date.</li><li>For government RFQs, include the reference and closing time.</li></ul></div></section><section class="section"><div class="wrap buyer-directory"><div class="directory-heading"><span class="eyebrow">Business and procurement</span><h2>Buy for your organisation.</h2><p>Choose the information relevant to your purchasing process.</p></div><div class="buyer-entries"><a href="#business"><h3>Businesses</h3><p>Office baskets, branch requirements and repeat supply.</p><span>Business supply →</span></a><a href="#government"><h3>Government buyers</h3><p>Specifications, RFQ schedules and submission deadlines.</p><span>Procurement enquiries →</span></a><a href="#schools"><h3>Schools</h3><p>Learner packs, book lists and classroom supplies.</p><span>School requirements →</span></a></div></div></section><section class="supplier-section"><div class="wrap supplier-layout"><div><span class="eyebrow">Supplier information</span><h2>Lepetse Business Enterprise<br>and Projects (Pty) Ltd</h2><p>Contact Lepetse to discuss your stationery requirement and delivery location.</p><a class="text-link" href="#contact">Contact and supplier enquiries</a></div><dl><div><dt>Telephone / WhatsApp</dt><dd><a href="tel:+27794404142">079 440 4142</a></dd></div><div><dt>Email</dt><dd><a href="mailto:admin@lepetse.co.za">admin@lepetse.co.za</a></dd></div><div><dt>Delivery coverage</dt><dd>To be confirmed for your location</dd></div><div><dt>Company profile and registrations</dt><dd>Verified details to be added</dd></div></dl></div></section>`}
const buyerPages={business:{label:'Business stationery supply',title:'Office stationery and repeat supply',intro:'Send a consolidated list for your office, branch or team. Include pack sizes, cost-centre references and your required delivery date.',list:['Paper, pens, files and everyday office essentials','Consolidated requirements across teams or cost centres','Once-off orders or a proposed replenishment schedule','Location and delivery needs captured with your request'],heading:'Specify your standard office basket.',text:'Send one list with the specifications your team uses. Include brands where required, acceptable alternatives and pack quantities, so the quotation can be prepared on a consistent basis.',extra:'For repeat supply, share your likely ordering frequency and typical basket. Payment terms, availability and delivery arrangements must be agreed for the order.'},government:{label:'Government procurement',title:'Stationery RFQs for government procurement',intro:'Share formal stationery RFQs and tender requirements for assessment against supply capacity, deadlines and the prescribed response process.',list:['Institution name and RFQ or tender reference','Full specification schedule and required quantities','Closing date and time, briefing requirements and addenda','Official submission instructions and delivery locations'],heading:'Include the complete RFQ pack.',text:'Send the original RFQ documents alongside the stationery list. Lepetse must review the requirements and confirm whether it can respond. Mandatory schedules and the institution’s submission rules govern any bid.',extra:'Submitting an RFQ through this prototype does not submit a bid to a government institution. CSD, tax and B-BBEE evidence must be verified and supplied through an appropriate channel; no registration or appointment is claimed here.'},schools:{label:'School and education stationery',title:'School stationery lists and learner packs',intro:'Exercise books, writing essentials, geometry sets and school stationery packs organised around your education requirements.',list:['Grade, class or programme stationery lists','Learner or pack quantities and contents per pack','Brand specifications and acceptable alternatives','Assembly, labelling and delivery requirements'],heading:'State quantities per learner and per pack.',text:'Attach your approved list and indicate whether quantities are per learner, per class or for the whole school. Include the number of packs and any specific book sizes, page counts or calculator models.',extra:'Share required dates early. Pack contents, assembly capacity, availability and delivery timing must be confirmed before an order is accepted.'}};
const conciseBuyers={business:{title:'Stationery for your business',intro:'Order everyday office supplies, replenish departments or send us your purchasing list for a quote.',heading:'Include with your list',list:['Item specifications, quantities and pack sizes','Branch or delivery locations','Cost-centre references, if required','Required date and replenishment frequency']},government:{title:'Government stationery RFQs',intro:'Share the complete RFQ pack so specifications, deadlines and response requirements can be assessed.',heading:'Required RFQ information',list:['Institution name and RFQ or tender reference','Specification schedules and all addenda','Closing date and time, plus any mandatory briefing','Official submission instructions and delivery locations']},schools:{title:'School stationery and learner packs',intro:'Send your school list for a quote on exercise books, classroom supplies and stationery packs.',heading:'Include with your school list',list:['Grade, class or programme','Contents and quantities per learner or pack','Total number of learners or packs','Book ruling, page counts and required calculator models','Required delivery date and any labelling instructions']}};
function buyerPage(type){if(type==='schools')return schoolsPage();if(type==='government')return governmentPage();if(type==='business')return businessPage();const p=conciseBuyers[type];return `<section class="buyer-intro"><div class="wrap"><span class="eyebrow">${buyerPages[type].label}</span><h1>${p.title}</h1><p>${p.intro}</p></div></section><section class="section buyer-brief"><div class="wrap"><div><h2>${p.heading}</h2><ul class="checklist">${p.list.map(x=>`<li>${x}</li>`).join('')}</ul>${type==='government'?'<p class="help">Sending an RFQ to Lepetse does not submit a bid to the issuing institution.</p>':''}</div><aside><a class="btn dark" href="#upload" data-buyer="${type}">Upload your list</a><p>Have products to select instead?<br><a href="#stationery">Browse products</a></p><a class="text-link" href="#faq">Ordering and delivery questions</a></aside></div></section>`}
function faq(){return pageHero('Help','Ordering and delivery','Answers to common purchasing questions.')+`<section class="section"><div class="wrap faq-content"><details open><summary>What should I include in a quotation request?</summary><p>Include the item specification, quantity, pack size, delivery location and required date. For a formal RFQ, attach the original schedules and submission instructions.</p></details><details><summary>Can I specify a brand or request alternatives?</summary><p>Yes. Provide the required brand or model and state whether alternatives are acceptable. Substitutions require your approval.</p></details><details><summary>Can you deliver to my location?</summary><p>Delivery coverage, cost and timing must be confirmed for your town, postcode and order. Include each site for a multi-location requirement.</p></details><details><summary>Does a request confirm an order?</summary><p>No. Pricing, availability, payment terms and delivery arrangements must be agreed before an order is accepted.</p></details><details><summary>Can I upload a list instead of choosing products?</summary><p>Yes. Use “Upload your list” to attach an RFQ, spreadsheet or school list. You do not need to select the same items in the catalogue.</p></details><details><summary>What happens to my prototype enquiry?</summary><p>The form prepares a printable enquiry you can download. It does not send your details or files to Lepetse. Only catalogue selections are saved on the device; contact details and attachments are cleared on reload.</p></details></div></section>`}
function aboutPage(){return pageHero('About Lepetse','People. Solutions. Progress.','Stationery supply for businesses, schools and public-sector procurement.')+`<section class="about-introduction"><div class="wrap about-story"><div><span class="eyebrow">Who we are</span><h2>Lepetse Business Enterprise and Projects (Pty) Ltd</h2><p>Lepetse supplies stationery for offices, schools and public-sector procurement. We work from your requirements to prepare quotations with clear product specifications, quantities and delivery arrangements.</p></div><div><h2>How we work</h2><p>We start with the details that matter to your order: the items you need, quantities, required specifications and delivery date.</p><p>Pricing, availability and delivery arrangements are confirmed before an order is agreed. Where clarification is needed, the requirements must be settled first.</p><a class="text-link" href="mailto:admin@lepetse.co.za?subject=Company%20and%20supplier%20information%20enquiry">Contact us for company or supplier information</a></div></div></section><section class="about-services" aria-labelledby="about-services-title"><div class="wrap"><h2 id="about-services-title">Our services</h2><dl class="about-service-list"><div><dt>Stationery supply</dt><dd>Office and school stationery supplied against your required specifications, quantities and preferred brands.</dd></div><div><dt>Product sourcing</dt><dd>Send us your stationery list. We’ll check the requested products and discuss suitable alternatives where needed.</dd></div><div><dt>Bulk quotations</dt><dd>Request itemised pricing for business, school and government stationery requirements.</dd></div><div><dt>School list fulfilment</dt><dd>Supply stationery against approved grade or classroom lists. Learner packing and labelling can be discussed when requesting a quote.</dd></div><div><dt>Repeat supply</dt><dd>Discuss recurring stationery requirements for your office or organisation.</dd></div><div><dt>Delivery arrangements</dt><dd>Delivery location, charges and expected lead times are confirmed as part of the quotation.</dd></div></dl><a class="btn dark" href="#upload">Request a quotation</a></div></section>`}
function contactPage(){return pageHero('Contact','Contact Lepetse','For stationery requirements and supplier enquiries.')+`<section class="section"><div class="wrap contact-simple"><div><h2>Telephone and WhatsApp</h2><a class="contact-number" href="tel:+27794404142">079 440 4142</a><a class="text-link" href="https://wa.me/27794404142" target="_blank" rel="noopener">Open WhatsApp</a><h2>Email</h2><a href="mailto:admin@lepetse.co.za">admin@lepetse.co.za</a></div><dl><div><dt>Operating address</dt><dd>To be confirmed</dd></div><div><dt>Business hours</dt><dd>To be confirmed</dd></div><div><dt>Delivery information</dt><dd><a href="#faq">Ordering and delivery questions</a></dd></div></dl></div></section>`}
function pageHero(label,title,text){return `<section class="page-hero"><div class="wrap"><span class="eyebrow">${label}</span><h1>${title}</h1><p>${text}</p></div></section>`}
function input(name,label,type='text',required=true,opts=''){const val=esc(formData[name]);return `<div class="field"><label for="${name}">${label}${required?' *':''}</label>${type==='select'?`<select name="${name}" id="${name}" ${required?'required':''}><option value="">Select an option</option>${opts.split('|').map(o=>`<option ${formData[name]===o?'selected':''}>${o}</option>`).join('')}</select>`:`<input id="${name}" name="${name}" type="${type}" value="${val}" ${required?'required':''}>`}</div>`}
function quote(){return `${pageHero('Request a quotation','Prepare a stationery quote request','No account needed. Prepare your quotation request in four steps. Required fields are marked with an asterisk.')}<section class="section"><div class="wrap rfq-layout"><div><div class="progress" aria-label="Request progress">${['Your details','Your list','Delivery','Review'].map((s,i)=>`<span class="${i===step?'active':''}" ${i===step?'aria-current="step"':''}>0${i+1} ${s}</span>`).join('')}</div><form id="rfq" novalidate><div id="form-content"></div><p id="form-error" class="error" role="alert"></p><div class="form-actions"><button class="btn outline" type="button" id="back">${step===0?'Browse stationery':'Back'}</button><button class="btn dark" type="submit">${step===3?'Prepare request summary ↓':'Continue →'}</button></div></form></div><aside class="rfq-aside">${approvalNote(formData.buyerType)}<h3>Need help?</h3><a href="#faq">Ordering and delivery questions</a><p><a href="tel:+27794404142">079 440 4142</a></p></aside></div></section>`}
function lineRows(){return items.map((x,i)=>`<div class="line-item"><div class="fields"><div class="field"><label for="desc${i}">Item description *</label><input id="desc${i}" data-line="${i}" data-key="description" value="${esc(x.description)}" placeholder="e.g. A4 paper, 80 gsm"></div><div class="field"><label for="qty${i}">Quantity *</label><input id="qty${i}" data-line="${i}" data-key="quantity" type="number" min="1" step="1" value="${esc(x.quantity)}"></div><div class="field"><label for="unit${i}">Unit / pack *</label><input id="unit${i}" data-line="${i}" data-key="unit" value="${esc(x.unit)}" placeholder="e.g. ream of 500"></div></div><button class="remove" type="button" data-remove="${i}">Remove item</button></div>`).join('')}
function renderStep(){if(!$('#form-content'))return;let h='';if(step===0)h=`<fieldset class="form-section"><legend>Tell us about your organisation</legend><div class="fields">${input('organisation','Organisation')}${input('buyerType','Buyer type','select',true,'Private business|Government / public entity|School / education|NGO|Other')}${input('contact','Contact person')}${input('email','Email address','email')}${input('phone','Telephone','tel',false)}${input('orderType','Order type','select',true,'Once-off requirement|Recurring office supply|School / project packs')}</div></fieldset>`;
if(step===1)h=`<fieldset class="form-section"><legend>What do you need?</legend><p class="help">Add complete item rows, attach a list, or do both. Category selections are starting points: confirm the specification, quantity and pack size.</p><div id="lines">${lineRows()}</div><button class="btn outline" type="button" id="add-line">＋ Add an item</button><div class="upload"><label for="files">Attach a stationery list</label><p class="help">Up to 5 files, 10 MB each. PDF, XLSX, CSV, DOCX, JPG or PNG. Files remain on your device in this prototype.</p><input id="files" type="file" multiple accept=".pdf,.xlsx,.csv,.docx,.jpg,.jpeg,.png"><div id="file-list" class="help">${selectedFiles.map(f=>esc(f.name)).join('<br>')}</div><button type="button" class="text-link" id="clear-files" style="border:0;background:none;padding:8px 0">Clear attachments</button></div><div class="fields" style="margin-top:20px">${input('alternatives','Are alternatives acceptable?','select',true,'Yes, subject to approval|No, exact specifications only|Please discuss')}<div class="field full"><label for="notes">Specifications or additional notes</label><textarea id="notes" name="notes">${esc(formData.notes)}</textarea></div></div></fieldset>`;
if(step===2)h=`<fieldset class="form-section"><legend>Where and when?</legend><div class="fields">${input('town','Delivery town / city')}${input('province','Province','select',true,'Eastern Cape|Free State|Gauteng|KwaZulu-Natal|Limpopo|Mpumalanga|North West|Northern Cape|Western Cape')}${input('postcode','Postcode')}${input('sites','Number of delivery sites','number')}${input('date','Required date','date')}${input('timing','Date flexibility','select',true,'Required on this date|Flexible, please discuss')}</div>${formData.buyerType==='Government / public entity'?`<h3>Formal RFQ details</h3><div class="fields">${input('reference','RFQ / tender reference')}${input('deadline','Closing date and time SAST','datetime-local')}${input('channel','Official submission channel')}${input('briefing','Mandatory briefing','select',true,'No|Yes, see RFQ documents|To be confirmed')}</div><p class="help">Attach the original RFQ on the previous step. Include addenda and briefing details in your notes.</p>`:''}</fieldset>`;
if(step===3)h=`<fieldset class="form-section"><legend>Review your request</legend><div class="review-group"><h3>Buyer</h3><p>${esc(formData.organisation)} · ${esc(formData.buyerType)}<br>${esc(formData.contact)} · ${esc(formData.email)}<br>${esc(formData.phone||'No telephone supplied')}<br>${esc(formData.orderType)}</p></div><div class="review-group"><h3>Stationery list</h3>${items.length?items.map(x=>`<p>${esc(x.quantity)} × ${esc(x.description)} — ${esc(x.unit)}</p>`).join(''):'<p>Requirements provided in attached list.</p>'}<p>Alternatives: ${esc(formData.alternatives)}</p><p>${esc(formData.notes)}</p><p>Attachments: ${selectedFiles.length?selectedFiles.map(x=>esc(x.name)).join(', '):'None'}</p></div><div class="review-group"><h3>Delivery and timing</h3><p>${esc(formData.town)}, ${esc(formData.province)}, ${esc(formData.postcode)}<br>${esc(formData.sites)} site(s) · ${esc(formData.date)}<br>${esc(formData.timing)}</p>${formData.buyerType==='Government / public entity'?`<p>RFQ: ${esc(formData.reference)}<br>Closes: ${esc(formData.deadline?.replace('T',' '))} SAST<br>Channel: ${esc(formData.channel)}<br>Briefing: ${esc(formData.briefing)}</p>`:''}</div><p class="help">This prototype processes the information in your browser only. The downloaded summary includes file names, not the files themselves. No stock, price, delivery date or order is confirmed.</p></fieldset>`;
$('#form-content').innerHTML=h;$('#back').onclick=()=>{capture();if(step===0)location.hash='stationery';else{step--;renderQuote()}};
$('#add-line')?.addEventListener('click',()=>{capture();items.push({description:'',quantity:1,unit:''});renderStep();updateCount()});$('#files')?.addEventListener('change',e=>{const files=[...e.target.files];const allowed=/\.(pdf|xlsx|csv|docx|jpe?g|png)$/i;if(files.length>5||files.some(f=>f.size>10*1024*1024||!allowed.test(f.name))){e.target.value='';$('#form-error').textContent='Choose up to five supported files, each no larger than 10 MB.';return}selectedFiles=files;$('#file-list').textContent=files.map(f=>f.name).join(', ');$('#form-error').textContent=''});$('#clear-files')?.addEventListener('click',()=>{selectedFiles=[];$('#files').value='';$('#file-list').textContent=''});
$('#lines')?.addEventListener('click',e=>{if(e.target.dataset.remove!==undefined){capture();items.splice(Number(e.target.dataset.remove),1);renderStep();updateCount()}});$('#rfq').onsubmit=e=>{e.preventDefault();capture();if(!validate())return;if(step<3){step++;renderQuote()}else finish()};}
function capture(){captureUpload();main.querySelectorAll('[data-basket-qty]').forEach(e=>{const q=Number(e.value);if(Number.isInteger(q)&&q>0&&q<=999999)items[Number(e.dataset.basketQty)].quantity=q});const form=$('#rfq');if(!form)return;new FormData(form).forEach((v,k)=>{if(typeof v==='string')formData[k]=v.trim()});form.querySelectorAll('[data-line]').forEach(e=>{items[Number(e.dataset.line)][e.dataset.key]=e.value.trim()});saveBasket()}
function validate(){const bad=[...$('#rfq').querySelectorAll('[required]')].find(e=>!e.checkValidity());if(bad){$('#form-error').textContent='Please complete the required fields using valid details.';bad.reportValidity();return false}let err='';if(step===1){if(!formData.organisation){step=0;renderQuote();$('#form-error').textContent='Enter your organisation and contact details to complete the enquiry.';return false}if(!items.length&&!selectedFiles.length)err='Add at least one item or attach your stationery list.';else if(formData.buyerType==="Government / public entity"&&!selectedFiles.length)err="Attach the original RFQ documents before continuing.";else if(items.some(i=>!i.description||!i.unit||!Number.isInteger(Number(i.quantity))||Number(i.quantity)<1))err='Complete each item with a description, positive whole quantity and unit or pack size, or remove unused rows.'}if(step===2){if(!/^\d{4}$/.test(formData.postcode))err='Enter a four-digit South African postcode.';else if(!Number.isInteger(Number(formData.sites))||Number(formData.sites)<1)err='Enter a positive whole number of delivery sites.';else if(formData.date<new Date().toLocaleDateString('en-CA',{timeZone:'Africa/Johannesburg'}))err='Select a future required date.';else if(formData.deadline&&formData.buyerType==='Government / public entity'&&new Date(formData.deadline+'+02:00')<=new Date())err='The closing deadline has passed. Check the date and time.'}$('#form-error').textContent=err;return !err}
function renderQuote(){main.innerHTML=quote();renderStep();applyPageBanner('quote');bindCommon();$('#rfq')?.scrollIntoView({block:'start',behavior:'smooth'})}
function finish(){showEnquiry({buyer:{...formData},items:items.map(x=>({...x})),attachments:selectedFiles.map(f=>({name:f.name,size:f.size}))},()=>{step=0;renderQuote()})}
function bindCommon(){bindProducts();const buyerRoute=location.hash.slice(1).split('?')[0];if(['business','government'].includes(buyerRoute)){const actions=main.querySelector('.business-ordering .actions');if(actions&&!actions.querySelector('[data-quote-catalogue]'))actions.insertAdjacentHTML('beforeend',`<a class="btn outline" data-quote-catalogue href="#stationery?mode=quote&buyer=${buyerRoute}">Build a quote from catalogue</a>`)}if(quotationMode()){const buyer=new URLSearchParams(location.hash.split('?')[1]||'').get('buyer');if(buyer==='business')formData.buyerType='Private business';if(buyer==='government')formData.buyerType='Government / public entity';}main.querySelectorAll('[data-business-intent]').forEach(a=>a.addEventListener('click',()=>{uploadDraft.orderType=a.dataset.businessIntent;formData.buyerType='Private business'}));main.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{items.push({...exampleItems[Number(b.dataset.example)]});updateCount();toast('Example added to your quote list. Edit it to match your requirements.');});main.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{const c=categories.find(c=>c[2]===b.dataset.add);items.push({description:c[0],quantity:1,unit:''});updateCount();toast(`${c[0]} added. Enter the specification and pack size in your quote list.`)});main.querySelectorAll('[data-buyer]').forEach(a=>a.onclick=()=>{step=0;formData.buyerType={business:'Private business',government:'Government / public entity',schools:'School / education'}[a.dataset.buyer]})}
function render(){if(!location.hash||location.hash==='#home'||location.hash==='#')history.replaceState(null,'','#stationery');const route=(location.hash.slice(1)||'stationery').split('?')[0];document.querySelector('nav').classList.remove('open');$('.menu').setAttribute('aria-expanded','false');document.querySelectorAll('nav a').forEach(a=>{if(a.hash===`#${route}`)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(route==='home')main.innerHTML=home();else if(buyerPages[route])main.innerHTML=buyerPage(route);else if(route==='stationery'){main.innerHTML=catalogue();bindCatalogue()}else if(route==='cart'){main.innerHTML=shoppingCartPage();bindShoppingCart()}else if(route==='checkout'){main.innerHTML=checkoutPage();bindCheckout()}else if(route==='basket'){main.innerHTML=basket();bindBasket()}else if(route.startsWith('product-')){main.innerHTML=productPage(route.slice(8))}else if(route==='upload'){main.innerHTML=uploadPage();bindUpload()}else if(route==='quote'){main.innerHTML=quote();renderStep()}else if(route==='about')main.innerHTML=aboutPage();else if(route==='contact')main.innerHTML=contactPage();else if(route==='faq')main.innerHTML=faq();else if(route==='privacy')main.innerHTML=pageHero('Prototype information','Your details stay on this device.','This is a review prototype, not a live customer procurement service.')+`<section class="section"><div class="wrap content"><h2>How the prototype handles information</h2><p>Shopping cart and quote basket product IDs, quantities and school-list grade and learner counts are saved on this device so the basket survives a refresh. Use Clear basket to remove them. Contact details, entered instructions and attachments stay in browser memory and are cleared on reload. Enquiries and files are not sent to Lepetse.</p><p>If you download a summary, that file contains the information you entered. Keep it secure and remove sample downloads when no longer needed. Hosting infrastructure may process ordinary access logs.</p><p>Telephone, email and WhatsApp links open external services. Information you choose to send there is handled by those services and the recipient.</p><h3>Before the public launch</h3><p>A live form requires secure storage and upload scanning, staff notifications, an approved privacy notice, retention rules and tested access controls. Legal identity, registrations, delivery coverage, trading terms and supplier documents also need verification.</p><p>For business enquiries, contact <a href="mailto:admin@lepetse.co.za">admin@lepetse.co.za</a>.</p></div></section>`;else main.innerHTML=pageHero('Page not found','Let’s get you back on track.','Use the navigation to explore stationery or prepare an enquiry.')+cta();
applyPageBanner(route);bindCommon();document.body.classList.toggle('school-detail-active',route==='schools'&&!!schoolSelectedGrade());if(route==='schools')bindSchoolLists();else stopSchoolSummaryObserver();updateCount();document.title=`${({home:'Stationery supply for organisations',stationery:'Stationery categories',quote:'Request a quote',business:'Business supply',government:'Government procurement',schools:'School stationery',about:'About',contact:'Contact',privacy:'Prototype privacy',faq:'Ordering and delivery',cart:'Shopping cart',checkout:'Checkout preview',basket:'Quote basket',upload:'Upload a procurement list'})[route]||(route.startsWith('product-')?products.find(p=>p.id===route.slice(8))?.name:'Page')||'Product'} | Lepetse`;finishCatalogueNavigation(route);}
$('.menu').onclick=()=>{const open=document.querySelector('nav').classList.toggle('open');$('.menu').setAttribute('aria-expanded',String(open))};$('#header-search').onsubmit=e=>{e.preventDefault();navigateCatalogueSearch($('#global-search').value.trim())};window.addEventListener('hashchange',()=>{beforeCatalogueNavigation();capture();render()});render();

function businessPage(){return `<section class="buyer-intro"><div class="wrap"><span class="eyebrow">Business stationery supply</span><h1>Office stationery for once-off and repeat orders</h1><p>Everyday stationery for your office, departments and branches.</p></div></section><section class="business-buying"><div class="wrap"><div class="business-ordering"><div><h2>Start your enquiry</h2><p>Choose the option that fits your purchasing needs.</p><div class="actions"><a class="btn dark" href="#upload?buyer=business" data-buyer="business" data-business-intent="Once-off quote">Request a once-off quote</a></div></div><aside class="business-next">${orderingJourney('Private business')}<a class="text-link" href="#faq">Ordering and delivery questions</a></aside></div></div></section>`}

function governmentPage(){return `<section class="buyer-intro"><div class="wrap"><span class="eyebrow">Government procurement</span><h1>Government stationery RFQs</h1><p>Stationery requirements for departments, municipalities and public entities.</p></div></section><section class="business-buying"><div class="wrap"><div class="business-ordering"><div><h2>Prepare an RFQ enquiry</h2><p>Send the issuing institution’s RFQ pack for assessment.</p><div class="actions"><a class="btn dark" href="#upload?buyer=government" data-buyer="government">Upload your RFQ</a></div><p class="help">Sending an RFQ to Lepetse does not submit a bid to the issuing institution.</p></div><aside class="business-next">${orderingJourney('Government / public entity')}<details><summary>Supplier documentation</summary><p>Request the company information and supporting evidence your institution requires, such as CSD details, tax-compliance information and applicable B-BBEE evidence. Availability and validity must be confirmed; this page does not claim registration or contract appointment.</p><a class="text-link" href="mailto:admin@lepetse.co.za?subject=Request%20for%20supplier%20documents&amp;body=Institution%3A%20%0ARFQ%20reference%3A%20%0ARequired%20documents%3A%20%0ADeadline%20%28SAST%29%3A%20">Request supplier documents</a></details><p class="help">Procurement enquiries: <a href="mailto:admin@lepetse.co.za">admin@lepetse.co.za</a><br><a href="tel:+27794404142">079 440 4142</a></p></aside></div></div></section>`}

function schoolsPage(){if(schoolSelectedGrade())return schoolListSection();return `<section class="buyer-intro"><div class="wrap"><span class="eyebrow">School and education stationery</span><h1>School stationery, organised around your list</h1><p>Request a quote for classroom supplies or learner packs by grade.</p></div></section>${schoolListSection()}<section class="business-buying"><div class="wrap"><div class="business-ordering"><div><h2>Start with your school list</h2><p>Attach your approved list and specify the grade, number of learners and whether quantities are per learner or totals.</p><div class="actions"><a class="btn dark" href="#upload?buyer=schools" data-buyer="schools">Upload your school list</a></div></div><aside class="business-next"><span class="eyebrow">What happens next</span><h2>Check the list before packing</h2><p>Specifications and quantities are reviewed before pricing, availability, packing and delivery arrangements are confirmed.</p><p class="help">Individual packing and labelling are requests, subject to confirmation.</p><p class="help">Online enquiries prepare a summary for review; they are not sent automatically.</p><a class="text-link" href="#faq">Ordering and delivery questions</a></aside></div></div></section>`}
